 let hm='<div class="xhm"><div class="xhy">'+P(['الاحتمال ↑','Probability ↑'])+'</div><div class="xhg">';for(let p=5;p>=1;p--){hm+='<span class="xl">'+p+'</span>';for(let i=1;i<=5;i++){const v=cnt[p+'_'+i]||0,c=lvC(p*i),on=XS.cell==p+'_'+i;hm+='<span class="xcell'+(on?' on':'')+'" style="background:'+(v?c[0]:c[1])+';color:'+(v?'#fff':c[0])+'" '+(v?'onclick="IDOOV.xset(\'cell\',\''+p+'_'+i+'\')"':'')+' title="'+p+'×'+i+'='+p*i+(v?' · '+v:'')+'">'+(v||'')+'</span>'}}hm+='<span></span>'+[1,2,3,4,5].map(i=>'<span class="xl">'+i+'</span>').join('')+'</div><div class="m" style="text-align:center;font-size:12px">'+P(['الأثر →','Impact →'])+'</div></div>';
