window.IDOOV.xall=v=>{if(!XS.el)return;XS.all=!!v;if(!v)XS.open={};XS.el.querySelectorAll('details[data-id]').forEach(d=>{d.open=!!v;XS.open[d.dataset.id]=!!v})};
const xAvg=a=>{const w=a.filter(k=>k._a!=null);return w.length?Math.round(w.reduce((s,k)=>s+Math.min(k._a,120),0)/w.length):null};
function xSumR(a){const hi=a.filter(r=>r._s>=15).length,md=a.filter(r=>r._s>=5&&r._s<15).length,lo=a.filter(r=>r._s&&r._s<5).length,od=a.filter(r=>r._od).length,oc=a.filter(r=>r.status=='occurred').length,T=a.length||1;
 return '<span class="xsum"><span class="xst">'+[[hi,'#d1101d'],[md,'#e0a32b'],[lo,'#0a6b3d'],[T-hi-md-lo,'#c3c8ce']].map(x=>x[0]?'<i style="width:'+x[0]/T*100+'%;background:'+x[1]+'"></i>':'').join('')+'</span>'+(hi?'<em class="r">▲ '+hi+'</em>':'')+(oc?'<em class="p">💥 '+oc+'</em>':'')+(od?'<em class="a">🔁 '+od+'</em>':'')+'</span>'}
function xSumK(a){const v=xAvg(a),c=SC(v),on=a.filter(k=>k._a!=null&&k._a>=95).length,w=a.filter(k=>k._a!=null&&k._a>=80&&k._a<95).length,off=a.filter(k=>k._a!=null&&k._a<80).length,T=a.length||1,mi=a.filter(k=>k._miss).length;
 return '<span class="xsum"><span class="xst">'+[[on,'#0a6b3d'],[w,'#e0a32b'],[off,'#d1101d'],[T-on-w-off,'#c3c8ce']].map(x=>x[0]?'<i style="width:'+x[0]/T*100+'%;background:'+x[1]+'"></i>':'').join('')+'</span><em style="background:'+c[1]+';color:'+c[0]+'">'+(v==null?'—':v+'%')+'</em>'+(mi?'<em class="a">⏳ '+mi+'</em>':'')+'</span>'}
const RS={open:['مفتوح','Open'],monitoring:['تحت المراقبة','Monitoring'],occurred:['وقع','Occurred'],closed:['مغلق','Closed']};
function xRowR(r,wp){const c=lvC(r._s),is=[];if(r.status=='occurred')is.push('💥 '+P(['وقع','occurred']));if(r._od)is.push('🔁 '+P(['مراجعة متأخرة','review overdue']));if(r._np)is.push('🎯 '+P(['بلا خطة/مسؤول','no plan/owner']));if(r.task_name)is.push('🔗 '+E(r.task_name)+' '+Math.round(+r.task_pc||0)+'%');
 return '<a class="xr" href="risks.html?pc='+encodeURIComponent(r.pcode)+'"><span class="xsc" style="background:'+c[1]+';color:'+c[0]+'">'+(r._s||'—')+'</span><div class="xn"><b>'+E(r.title)+'</b><small>'+(wp?E(pn(XD,r.pcode))+' · ':'')+P(RS[r.status]||[r.status,r.status])+' · 👤 '+E(r.owner_id?(US[r.owner_id]||'—'):(r.owner_name||'—'))+(r.review_at?' · 🗓 '+fd(r.review_at):'')+(r.prob?' · '+P(['احتمال ','P '])+r.prob+'×'+P(['أثر ','I '])+r.impact:'')+'</small>'+(r.response?'<div class="xresp">🎯 '+E(String(r.response).slice(0,160))+'</div>':'')+(is.length?'<div class="xis">'+is.join(' · ')+'</div>':'')+'</div></a>'}
